SELECT CASE WHEN c.age >= 69 THEN 'high' WHEN c.age >= 38 THEN 'mid' ELSE 'low' END AS age_bucket, COUNT(CASE WHEN t.merchant = 'Shell' THEN 1 END) AS shell_count, ROUND((100 * SUM(CASE WHEN t.merchant = 'Shell' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_shell FROM transactions t INNER JOIN accounts a ON t.account_id = a.id INNER JOIN customers c ON a.customer_id = c.id WHERE t.account_id = 28 GROUP BY CASE WHEN c.age >= 69 THEN 'high' WHEN c.age >= 38 THEN 'mid' ELSE 'low' END ORDER BY shell_count DESC;
